import { cloneValue } from './clone-value.mjs';
export const DELETE=Symbol('delete');
export function mergeLayers(...layers) {
  const out={};
  for(const layer of layers) if(layer) for(const key of Object.keys(layer)) out[key]=cloneValue(layer[key]);
  return out;
}

